namespace sv_c3b4192891454546a81e3e807c1959db.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_c3b4192891454546a81e3e807c1959db.Models;

namespace sv_c3b4192891454546a81e3e807c1959db.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300); // Simulate validation
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_c3b4192891454546a81e3e807c1959db.Components.Pages.JobApplication

<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step @cssClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></div>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@namespace sv_c3b4192891454546a81e3e807c1959db.Components.Pages.JobApplication

<div class="work-entry-form card">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h5 class="card-title mb-0">Position @(Index + 1)</h5>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name *</label>
                <input type="text" class="form-control" value="@Company"
                       @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title *</label>
                <input type="text" class="form-control" value="@Title"
                       @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date *</label>
                <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => UpdateStartDate(e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                       disabled="@IsCurrent"
                       @onchange="e => UpdateEndDate(e.Value?.ToString())" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check">
                    <input type="checkbox" class="form-check-input" id="current-@Index"
                           checked="@IsCurrent" @onchange="e => UpdateIsCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="current-@Index">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter, EditorRequired] public string Company { get; set; } = "";
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter, EditorRequired] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter, EditorRequired] public string Description { get; set; } = "";
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);

    private async Task UpdateField(string field, string? value)
    {
        var data = field switch
        {
            nameof(Company) => new WorkEntryData(value ?? "", Title, StartDate, EndDate, IsCurrent, Description),
            nameof(Title) => new WorkEntryData(Company, value ?? "", StartDate, EndDate, IsCurrent, Description),
            nameof(Description) => new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, value ?? ""),
            _ => GetCurrentData()
        };
        await OnChanged.InvokeAsync(data);
    }

    private async Task UpdateStartDate(string? value)
    {
        var date = DateTime.TryParse(value, out var d) ? d : DateTime.Today;
        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, date, EndDate, IsCurrent, Description));
    }

    private async Task UpdateEndDate(string? value)
    {
        DateTime? date = DateTime.TryParse(value, out var d) ? d : null;
        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, date, IsCurrent, Description));
    }

    private async Task UpdateIsCurrent(bool isCurrent)
    {
        var endDate = isCurrent ? null : EndDate;
        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, endDate, isCurrent, Description));
    }

    private WorkEntryData GetCurrentData() => new(Company, Title, StartDate, EndDate, IsCurrent, Description);
}

