+            _ => GetCurrentData()
+        };
+        await OnChanged.InvokeAsync(data);
+    }
+
+    private async Task UpdateStartDate(string? value)
+    {
+        var date = DateTime.TryParse(value, out var d) ? d : DateTime.Today;
+        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, date, EndDate, IsCurrent, Description));
+    }
+
+    private async Task UpdateEndDate(string? value)
+    {
+        DateTime? date = DateTime.TryParse(value, out var d) ? d : null;
+        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, date, IsCurrent, Description));
+    }
+
+    private async Task UpdateIsCurrent(bool isCurrent)
+    {
+        var endDate = isCurrent ? null : EndDate;
+        await OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, endDate, isCurrent, Description));
+    }
+
+    private WorkEntryData GetCurrentData() => new(Company, Title, StartDate, EndDate, IsCurrent, Description);
+}
