+    <h1 class="mb-4">Job Application</h1>
+
+    <StepIndicator CurrentStep="currentStep"
+                   CompletedSteps="completedSteps"
+                   OnStepSelected="GoToStep" />
+
+    <div class="mt-4">
+        @switch (currentStep)
+        {
+            case 0:
+                <PersonalInfoStep FullName="@personalFullName"
+                                  Email="@personalEmail"
+                                  Phone="@personalPhone"
+                                  Address="@personalAddress"
+                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
+                                  OnNext="HandlePersonalNext" />
+                break;
+
+            case 1:
+                <WorkHistoryStep Entries="workEntries"
+                                 OnNext="HandleWorkNext"
+                                 OnBack="GoBack" />
+                break;
+
+            case 2:
+                <ReferencesStep References="references"
+                                OnNext="HandleReferencesNext"
+                                OnBack="GoBack" />
+                break;
+
+            case 3:
+                <CoverLetterStep CoverLetter="@coverLetter"
+                                 OnNext="HandleCoverLetterNext"
+                                 OnBack="GoBack" />
+                break;
+
+            case 4:
+                <ReviewStep Personal="@GetPersonalInfo()"
+                            WorkEntries="@GetWorkEntries()"
+                            References="@GetReferences()"
+                            CoverLetter="@coverLetter"
+                            OnBack="GoBack"
+                            OnEditSection="GoToStep"
+                            OnSubmit="HandleSubmit"
+                            IsSubmitting="isSubmitting"
+                            IsSubmitted="isSubmitted"
+                            ApplicationId="applicationId"
+                            ErrorMessage="@submitError" />
+                break;
+        }
+    </div>
+</div>
+
+@code {
+    private int currentStep = 0;
+    private HashSet<int> completedSteps = new();
+
+    // Personal Info state
+    private string personalFullName = "";
+    private string personalEmail = "";
+    private string personalPhone = "";
+    private string personalAddress = "";
+
+    // Work History state
+    private List<WorkHistoryStep.WorkEntryState> workEntries = new();
+
+    // References state
+    private List<ReferencesStep.ReferenceState> references = new();
+
+    // Cover Letter state
+    private string coverLetter = "";
+
+    // Submission state
+    private bool isSubmitting;
+    private bool isSubmitted;
+    private int applicationId;
+    private string? submitError;
+
+    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        personalFullName = result.FullName;
+        personalEmail = result.Email;
+        personalPhone = result.Phone;
+        personalAddress = result.Address;
+        completedSteps.Add(0);
+        currentStep = 1;
+    }
+
+    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryState> entries)
+    {
+        workEntries = entries;
+        completedSteps.Add(1);
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferencesStep.ReferenceState> refs)
+    {
+        references = refs;
+        completedSteps.Add(2);
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string letter)
+    {
+        coverLetter = letter;
+        completedSteps.Add(3);
+        currentStep = 4;
+    }
+
+    private void GoBack()
+    {
+        if (currentStep > 0)
+            currentStep--;
+    }
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        submitError = null;
+
+        try
+        {
+            var application = new JobApplication(
+                GetPersonalInfo(),
+                new WorkHistory(workEntries.Select(e =>
+                    new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
+                references.Select(r =>
+                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                coverLetter
+            );
+
+            applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            submitError = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    private PersonalInfo GetPersonalInfo() =>
+        new(personalFullName, personalEmail, personalPhone, personalAddress);
+
+    private List<ReviewStep.WorkEntryInfo> GetWorkEntries() =>
+        workEntries.Select(e => new ReviewStep.WorkEntryInfo(
+            e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();
+
+    private List<ReviewStep.ReferenceInfo> GetReferences() =>
+        references.Select(r => new ReviewStep.ReferenceInfo(
+            r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+}
